pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        // The inner call must not revert; otherwise the outer transfer itself reverts.
        // To ensure the inner calls succeed, we deploy a helper that simply returns true for the expected selector.
        // This lets the fuzzer supply any caddress that implements the interface successfully.
        Helper helper = new Helper();
        caddress = address(helper);
        // ensure non-empty _tos array as required
        vm.assume(_tos.length > 0);
        bool success;
        bool result;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = true;
            result = ret;
        } catch {
            success = false;
        }
        if (success) {
            // When the call succeeds, the reference always returns true.
            // The mutant returns false, violating this property.
            assertTrue(result);
        } else {
            // If it reverted, we are not asserting anything about return value.
            assertTrue(true);
        }
    }
}

contract Helper {
    fallback() external payable returns (bool) {
        // mimic a successful ERC20 transferFrom
        return true;
    }
}

